INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind alle Prozessoren Mikroprozessoren?', 2, '[{"text": "Nein", "correct": true, "because": "Prozessoren umfassen auch ältere Technologien"}, {"text": "Ja", "correct": false, "because": "Nicht alle sind integrierte Schaltkreise"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist die Hauptaufgabe eines Prozessors?', 3, '[{"text": "Befehle ausführen", "correct": true, "because": "Verarbeitet Daten gemäß Programmen"}, {"text": "Daten speichern", "correct": false, "because": "Aufgabe des Speichers"}, {"text": "Grafik rendern", "correct": false, "because": "Aufgabe der GPU"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu einem Prozessor?', 5, '[{"text": "Rechenwerk", "correct": true, "because": "Führt Berechnungen durch"}, {"text": "Steuerwerk", "correct": true, "because": "Koordiniert Abläufe"}, {"text": "Festplatte", "correct": false, "because": "Externer Speicher"}, {"text": "Bildschirm", "correct": false, "because": "Ausgabegerät"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Prozessor hat mehrere Kerne. b) Alle Prozessoren haben integrierte Grafik.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) nicht bei allen CPUs"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines Prozessors?', 4, '[{"text": "Taktfrequenz", "correct": false, "because": "Beeinflusst Leistung"}, {"text": "Kernanzahl", "correct": false, "because": "Bestimmt Multitasking"}, {"text": "Musikwiedergabe", "correct": true, "because": "Irrelevant für CPU"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Prozessor ohne Cache funktioniert?', 2, '[{"text": "Ja", "correct": true, "because": "Cache optional, aber leistungsfördernd"}, {"text": "Nein", "correct": false, "because": "Cache nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die Prozessorleistung?', 3, '[{"text": "Kernanzahl", "correct": true, "because": "Mehr Kerne, mehr Aufgaben"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Leistungsfaktor"}, {"text": "Manuelle Kühlung", "correct": false, "because": "Kühlung sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prozessorarten gibt es?', 5, '[{"text": "Hauptprozessor", "correct": true, "because": "Zentrale CPU"}, {"text": "Koprozessor", "correct": true, "because": "Z. B. GPU"}, {"text": "Cloudprozessor", "correct": false, "because": "Kein Standardbegriff"}, {"text": "Musikprozessor", "correct": false, "because": "Nicht definiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Prozessoren steuern Datenflüsse. b) Sie sind nur in PCs relevant. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) auch in Smartphones etc."}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Prozessorauswahl?', 4, '[{"text": "Sockelkompatibilität", "correct": false, "because": "Muss zum Mainboard passen"}, {"text": "Leistungsbedarf", "correct": false, "because": "Bestimmt Einsatz"}, {"text": "Bildschirmauflösung", "correct": true, "because": "Irrelevant für CPU"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Haben alle Prozessoren mehrere Kerne?', 2, '[{"text": "Nein", "correct": true, "because": "Ältere Modelle oft Single-Core"}, {"text": "Ja", "correct": false, "because": "Nicht universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hersteller produzieren Prozessoren?', 4, '[{"text": "Intel", "correct": true, "because": "Marktführer für CPUs"}, {"text": "AMD", "correct": true, "because": "Ryzen-Serie bekannt"}, {"text": "Microsoft", "correct": false, "because": "Kein CPU-Hersteller"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Prozessoren immer heiß werden. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Wärmeentwicklung durch Berechnungen"}, {"text": "Nein", "correct": false, "because": "Kühlung managt Hitze"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Prozessorauswahl?', 3, '[{"text": "Leistung", "correct": true, "because": "Bestimmt Anwendungstauglichkeit"}, {"text": "Größe", "correct": false, "because": "Sockel entscheidet"}, {"text": "Manuelle Kühlung", "correct": false, "because": "Automatische Systeme besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Prozessoren haben Cache-Speicher. b) Sie arbeiten ohne Strom.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) benötigen Energie"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften beeinflussen die Prozessorleistung?', 5, '[{"text": "Taktfrequenz", "correct": true, "because": "Bestimmt Geschwindigkeit"}, {"text": "Kernanzahl", "correct": true, "because": "Fördert Multitasking"}, {"text": "Gehäusefarbe", "correct": false, "because": "Kein Leistungsfaktor"}, {"text": "Bildschirmgröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Prozessor unwichtig?', 3, '[{"text": "Cache-Größe", "correct": false, "because": "Beeinflusst Zugriffsgeschwindigkeit"}, {"text": "Energieverbrauch", "correct": false, "because": "Wichtig für Effizienz"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein CPU-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Prozessor mit einem Kern noch üblich ist?', 2, '[{"text": "Nein", "correct": true, "because": "Multi-Core ist Standard"}, {"text": "Ja", "correct": false, "because": "Selten in modernen Geräten"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Prozessoren nur in Computern?', 3, '[{"text": "Nein", "correct": true, "because": "Auch in Smartphones, Autos etc."}, {"text": "Ja", "correct": false, "because": "Vielfältige Einsätze"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu Prozessoren?', 4, '[{"text": "Betrieb eines Gaming-PCs", "correct": true, "because": "Verarbeitet Spielberechnungen"}, {"text": "Musikwiedergabe", "correct": false, "because": "Sekundäre Aufgabe"}, {"text": "Bildbearbeitung", "correct": false, "because": "GPU oft relevanter"}]');
